export class CRuleBranch {
	private pattern: string
	private lCode: string[] = []

	constructor(
			pattern1: string,
			lCode: string[] = []
			) {

		this.pattern = pattern1;

		for (const str of lCode) {
			this.lCode.push(str)
		}
	}

	// ..........................................................

	addCode(
			line: string
			): void {

		const lMatches = line.match(/^(\s*)return\s+(.*)$/)
		if (defined(lMatches)) {
			const [_, prefix, valueStr] = lMatches
			if (valueStr.includes('$skip')) {
				this.lCode.push(line)
			}
			else {
				const len = valueStr.length
				const useStr = (
					  valueStr.endsWith(';')
					? valueStr.substring(0, len-1)
					: valueStr
					)

				this.lCode.push((prefix + 'return pm.returnVal(' + useStr + ');'))
			}
		}
		else {
			this.lCode.push(line)
		}
		return
	}

	// ..........................................................

	patternStr(): string {

		if (isEmpty(this.lCode)) {
			return this.pattern
		}
		else {
			const hashPos = this.pattern.indexOf('#')
			if (hashPos === -1) {
				return this.pattern + ' ->'
			}
			else {
				return this.pattern.replace('#', '-> #')
			}
		}
	}

	// ..........................................................

	numCodeLines(): number {

		return this.lCode.length
	}

	// ..........................................................
	// ASYNC

	async asString(
			type: THeraType = 'civet'
			): AutoPromise<string> {

		const patStr = this.patternStr()
		const code = await mkCodeBlock(this.lCode, type)
		return toBlock([patStr, indented(code)])
	}
}

